CREATE OR REPLACE FUNCTION check_series_uniformity(p_series_id bigint)
RETURNS boolean AS $$
BEGIN
    RETURN EXISTS (
        SELECT 1
        FROM core
        WHERE series_id = p_series_id
        GROUP BY series_id
        HAVING COUNT(DISTINCT canonical_name) = 1
    );
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION check_series_uniformity()
RETURNS TABLE(series_id bigint, uniform boolean) AS $$
BEGIN
    RETURN QUERY
    SELECT c.series_id, 
           (COUNT(DISTINCT c.canonical_name) = 1) as uniform
    FROM core c
    GROUP BY c.series_id;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION check_series_uniformity(p_content_key bigint)
RETURNS boolean AS $$
DECLARE
    v_series_id bigint;
BEGIN
    SELECT series_id INTO v_series_id FROM core WHERE content_key = p_content_key;
    RETURN EXISTS (
        SELECT 1 FROM core 
        WHERE series_id = v_series_id 
        GROUP BY series_id 
        HAVING COUNT(DISTINCT canonical_name) = 1
    );
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION check_series_uniformity(p_series_id bigint) RETURNS boolean AS $$
BEGIN
    RETURN (SELECT COUNT(DISTINCT canonical_name) = 1 FROM core WHERE series_id = p_series_id);
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION check_series_uniformity() RETURNS SETOF core AS $$
BEGIN
    RETURN QUERY SELECT DISTINCT ON (c.series_id) c.* FROM core c ORDER BY c.series_id, c.canonical_name;
END;
$$ LANGUAGE plpgsql;
